    35	    public synchronized Reservation create(NewReservation request) {
    36	        if (!request.checkOut().isAfter(request.checkIn())) {
    37	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    38	        }
    39	        if (request.guests() < 1) {
    40	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    41	        }
    42	        Room room = rooms.find(request.roomNumber())
